module TopModule (
    input  in1,
    input  in2,
    input  in3,
    output out
);

    wire xnor_out;
    wire xor_out;

    // Two-input XNOR gate
    assign xnor_out = ~(in1 ^ in2);

    // Two-input XOR gate with xnor_out and in3
    assign xor_out = xnor_out ^ in3;

    // Output assignment
    assign out = xor_out;

endmodule

module TopModule (
    input  wire [7:0] a,
    input  wire [7:0] b,
    output wire [7:0] s,
    output wire       overflow
);

    wire [7:0] sum;
    wire       overflow_flag;

    assign sum = a + b;

    // Compute overflow for signed addition
    assign overflow_flag = (a[7] & b[7] & (~sum[7])) | 
                          (~a[7] & ~b[7] & sum[7]);

    assign s = sum;
    assign overflow = overflow_flag;

endmodule

