module DFF (
    input  d,
    input  clk,
    output q
);

    always @(posedge clk) begin
        q <= d;
    end

endmodule

module TopModule (
    input  a,
    input  b,
    output out_or_bitwise,
    output out_or_logical,
    output out_not
);

    // Compute bitwise OR of a and b
    assign out_or_bitwise = a | b;

    // Compute logical OR of a and b
    assign out_or_logical = (a != 3'b0) || (b != 3'b0);

    // Compute NOT of a and b
    wire [5:0] not_a_b;
    assign not_a_b[2:0] = ~a;
    assign not_a_b[5:3] = ~b;

    // Assign the result to out_not
    assign out_not = not_a_b;

endmodule

